    <!-- 支付成功卡片 -->
    <view class="card success-card">
      <view class="icon">
        <text class="icon-check">✓</text>
      </view>
      <text class="main-title">支付成功！</text>
      <text class="desc">您的陪诊订单已确认，陪诊员将在10-30分钟内与您联系</text>
      <!-- 新增：查看订单详情按钮 -->
      <button class="view-order-btn" @click="goToOrderDetail">查看订单详情</button>
    </view>

    <!-- 订单信息 -->
    <view class="card order-info">
      <view class="title"><text class="iconfont">📝</text> 订单信息</view>
      <view class="info-item">
        <text class="label">订单编号</text>
        <text class="value">{{ orderData.orderNo || 'PZ202311150001' }}</text>
      </view>
      <view class="info-item">
        <text class="label">支付金额</text>
        <text class="value">¥{{ formatAmount(orderData.amount) }}</text>
      </view>
      <view class="info-item">
        <text class="label">支付时间</text>
        <text class="value">{{ payTime }}</text>
      </view>
      <view class="info-item">
        <text class="label">支付方式</text>
        <text class="value">微信支付</text>
      </view>
    </view>

    <!-- 服务详情 -->
    <view class="card service-detail">
      <view class="title"><text class="iconfont">💼</text> 服务详情</view>
      <view class="info-item">
        <text class="label">陪诊师</text>
        <text class="value">{{ orderData.attendantName || '王丽' }}</text>
      </view>
      <!-- 修改：联系电话展示完全 -->
      <view class="info-item">
        <text class="label">联系电话</text>
        <text class="value">{{ orderData.attendantPhone || '13800138000' }}</text>
      </view>
      <view class="info-item">
        <text class="label">就诊时间</text>
        <text class="value">{{ orderData.serviceTime || '2023年11月15日 上午9:30' }}</text>
      </view>
      <view class="info-item">
        <text class="label">就诊医院</text>
        <text class="value">{{ orderData.hospital || '北京协和医院' }}</text>
      </view>
      <view class="info-item">
        <text class="label">就诊人</text>
        <text class="value">{{ orderData.contactPerson || '张三' }}</text>
      </view>
      <view class="info-item" v-if="orderData.contactPhone">
        <text class="label">联系方式</text>
        <text class="value">{{ orderData.contactPhone }}</text>
      </view>
      <!-- 修改：服务类型固定为“普通陪诊” -->
      <view class="info-item">
        <text class="label">服务类型</text>
        <text class="value">普通陪诊</text>
      </view>
      <view class="info-item" v-if="orderData.specialRequirements">
        <text class="label">特殊要求</text>
        <text class="value">{{ orderData.specialRequirements }}</text>
      </view>
    </view>

    <!-- 核销二维码 -->
    <view class="card qr-code-card">
      <view class="title">陪诊核销二维码</view>
      <!-- 优先使用 Base64 二维码，否则回退到 URL 生成 -->
      <image :src="qrCodeSrc" class="qrcode" mode="widthFix" @error="handleQrError"></image>
      <text class="tip">陪诊师将扫描此码确认服务，请妥善保存</text>
      <view class="btn-group">
        <button class="save-btn" @click="saveQRCode">保存二维码</button>
        <button class="refresh-btn" @click="refreshQRCode">刷新</button>
      </view>
    </view>
  </view>
</template>

<script>
export default {
  data() {
    return {
      orderData: {
        amount: 0,
        attendantName: '',
        attendantPhone: '', // 新增：陪诊师电话
        attendantAvatar: '', // 新增：陪诊师头像 (如果需要保存)
        hospital: '',
        orderNo: '',
        qrCodeBase64: '',
        serviceTime: '',
        contactPerson: '',
        contactPhone: '',
        selectedServices: [],
        specialRequirements: '',
        serviceType: '普通陪诊',
        payTime: new Date().toLocaleString(),
        paymentMethod: '微信支付',
        // 从 OrderConfirmPage 传递过来的 avatarUrl
        avatarUrl: '',
      },
      payTime: '', // 动态支付时间
      qrCodeSrc: '' // 二维码图片 src
    };
  },
  onLoad(options) {
    // 获取当前支付时间
    const now = new Date();
    this.payTime = now.getFullYear() + '-' +
                   String(now.getMonth() + 1).padStart(2, '0') + '-' +
                   String(now.getDate()).padStart(2, '0') + ' ' +
                   String(now.getHours()).padStart(2, '0') + ':' +
                   String(now.getMinutes()).padStart(2, '0') + ':' +
                   String(now.getSeconds()).padStart(2, '0');

    // 尝试从 Storage 获取完整订单数据
    let storedData = null;
    try {
      storedData = uni.getStorageSync('orderConfirmData');
    } catch (e) {
      console.warn('从 Storage 读取订单数据失败', e);
    }

    // 若无 Storage 数据，尝试用 orderNo 重建（简化）
    if (!storedData || !storedData.orderNo) {
      // 使用 URL 参数中的 orderNo（如有）
      const orderNo = options.orderNo || 'PZ202311150001';
      storedData = {
        orderNo,
        amount: 19800, // 示例值（单位：分）
        attendantName: '王丽',
        attendantPhone: '13800138000', // 示例值：陪诊师电话
        attendantAvatar: '/static/default-avatar.jpg', // 示例值：陪诊师头像
        avatarUrl: '/static/default-avatar.jpg', // 示例值：avatarUrl
        hospital: '北京协和医院',
        serviceTime: '2023年11月15日 上午9:30',
        contactPerson: '张三',
        contactPhone: '13800138001',
        selectedServices: ['consult', 'exam'],
        specialRequirements: '请协助取药',
        qrCodeBase64: '',
        serviceType: '普通陪诊',
        payTime: this.payTime,
        paymentMethod: '微信支付'
      };
    }

    // 将获取到的数据赋值给 orderData
    this.orderData = { ...storedData };

    // --- 新增：保存陪诊师电话到本地存储 ---
    // 保存到特定订单 key 下，便于后续查询
    const orderKey = `order_${storedData.orderNo}`;
    const updatedStoredData = { ...storedData };
    uni.setStorageSync(orderKey, updatedStoredData); // 保存完整数据
    // 也保存一份到 orderConfirmData (如果需要)
    uni.setStorageSync('orderConfirmData', updatedStoredData);
    // --- 新增结束 ---

    // 设置二维码源，包含所有信息
    this.updateQrCode();

    // ========== 修改：将订单添加到全局订单列表，确保数据结构匹配 order.vue ==========
    // 1. 从本地存储获取现有的订单列表
    let existingOrders = uni.getStorageSync('all_orders') || [];
    console.log('【调试】当前已存在的订单列表:', existingOrders);

    // 2. 创建符合 order.vue 需求的订单对象结构
    // 注意：需要解析 serviceTime 为 date 和 time
    const serviceTimeParts = storedData.serviceTime ? storedData.serviceTime.split(' ') : [];
    const serviceDate = serviceTimeParts[0] || '未知日期';
    const startTime = serviceTimeParts[1] || '未知时间';

    // 确保金额格式正确 (从分转为元字符串)
    const formattedPrice = `¥${this.formatAmount(storedData.amount)}`;

    // --- 关键修改：确定陪诊师头像字段 ---
    // 优先使用 avatarUrl (来自 OrderConfirmPage 传递)，否则回退到 attendantAvatar 或默认值
    const attendantAvatarToUse = storedData.avatarUrl || storedData.attendantAvatar || '/static/default-avatar.jpg';
    // --- 结束修改 ---

    const orderForList = {
      id: storedData.orderNo, // 使用订单号作为唯一ID
      orderId: storedData.orderNo, // 与 OrderDetailPage 兼容
      serviceType: storedData.serviceType || '普通陪诊',
      hospitalName: storedData.hospital || '未知医院',
      serviceDate: serviceDate, // 提取日期部分
      startTime: startTime, // 提取时间部分
      status: 'assigned', // <--- 修改：支付成功后，订单状态应为 'assigned' (待接单)
      price: formattedPrice, // 确保格式正确
      attendantAvatar: attendantAvatarToUse, // <--- 关键：使用确定的头像路径
      doctorAvatar: attendantAvatarToUse, // 兼容旧字段，如果 order.vue 仍在使用
      attendantName: storedData.attendantName, // 新增：陪诊师姓名
      doctorName: storedData.attendantName || storedData.doctorName || '未知陪诊师', // 兼容旧字段
      rating: 5, // 假设默认评分
      // 添加其他可能需要的字段
      amount: storedData.amount, // 以分为单位的金额
      attendantPhone: storedData.attendantPhone, // 陪诊师电话
      contactPerson: storedData.contactPerson, // 就诊人
      payTime: storedData.payTime || this.payTime, // 支付时间
      paymentMethod: storedData.paymentMethod || '微信支付' // 支付方式
    };

    // 3. 检查是否已存在相同ID的订单 (避免重复)
    const exists = existingOrders.some(order => order.id === orderForList.id);
    if (!exists) {
      existingOrders.unshift(orderForList); // 添加到列表开头，最新订单在前
      console.log('【调试】添加新订单到列表:', orderForList);
    } else {
      console.log('【调试】订单已存在，未添加:', orderForList.id);
      // 如果订单已存在，可以考虑更新其状态等信息
      const index = existingOrders.findIndex(order => order.id === orderForList.id);
      if (index !== -1) {
        // 更新现有订单信息，但保留其可能已经改变的状态（例如，如果它已经被接单）
        // 这里可以更精细地判断是否需要更新状态
        // 例如，只有当原状态是 'pending' 时，才更新为 'assigned'
        const currentStatus = existingOrders[index].status;
        // 如果当前状态已经是 'assigned', 'in_progress', 'completed', 'cancelled'，则不更新为 'assigned'
        if (currentStatus === 'pending' || currentStatus === 'completed') { // 'completed' 是之前的错误状态，也应更新
          existingOrders[index] = {
            ...existingOrders[index],
            ...orderForList
          };
          console.log('【调试】已更新现有订单状态:', orderForList.id);
        } else {
          // 否则，只更新其他信息，不更新状态
          const { status: _, ...orderForListWithoutStatus } = orderForList; // 解构排除 status
          existingOrders[index] = {
            ...existingOrders[index],
            ...orderForListWithoutStatus
          };
          console.log('【调试】已更新现有订单其他信息，保留原状态:', orderForList.id, currentStatus);
        }
      }
    }

    // 4. 保存更新后的订单列表
    uni.setStorageSync('all_orders', existingOrders);
    console.log('【调试】已保存更新后的订单列表:', existingOrders);
    // ========== 结束修改 ==========
  },
  methods: {
    formatAmount(amount) {
      // 假设 amount 单位是“分”，转换为“元”
      // 如果后端返回的是“元”，请改为 return amount.toFixed(2)
      if (typeof amount !== 'number' || isNaN(amount)) {
         return '0.00';
      }
      return (amount / 100).toFixed(2);
    },
    updateQrCode() {
      // 回退到 URL 生成二维码，包含所有订单信息
      // 将订单信息格式化为一个字符串
      const qrContent = JSON.stringify({
        orderNo: this.orderData.orderNo,
        attendantName: this.orderData.attendantName,
        attendantPhone: this.orderData.attendantPhone,
        hospital: this.orderData.hospital,
        serviceTime: this.orderData.serviceTime,
        contactPerson: this.orderData.contactPerson,
        contactPhone: this.orderData.contactPhone,
        serviceType: '普通陪诊',
        specialRequirements: this.orderData.specialRequirements,
        amount: this.formatAmount(this.orderData.amount)
      });

      // 使用 encodeURIComponent 确保中文和特殊字符正确编码
      this.qrCodeSrc = `https://api.qrserver.com/v1/create-qr-code/?data=${encodeURIComponent(qrContent)}&size=200x200`;
      console.log('【调试】生成的二维码内容:', qrContent);
    },
    handleQrError() {
      console.warn('二维码加载失败，尝试刷新');
    },
    saveQRCode() {
      // 下载并保存二维码图片
      uni.downloadFile({
        url: this.qrCodeSrc,
        success: (res) => {
          if (res.statusCode === 200) {
            uni.saveImageToPhotosAlbum({
              filePath: res.tempFilePath,
              success: () => {
                uni.showToast({ title: '已保存到相册' });
              },
              fail: () => {
                uni.showToast({ title: '保存失败，请允许相册权限', icon: 'none' });
              }
            });
          } else {
            uni.showToast({ title: '下载失败', icon: 'none' });
          }
        },
        fail: () => {
          uni.showToast({ title: '下载二维码失败', icon: 'none' });
        }
      });
    },
    refreshQRCode() {
      this.updateQrCode();
      uni.showToast({ title: '二维码已刷新', icon: 'success' });
    },
    // 新增：跳转到订单详情页的方法 (修改：使用 redirectTo)
    goToOrderDetail() {
      // 确保有订单号
      if (this.orderData.orderNo) {
        // 使用 uni.redirectTo 替代 uni.navigateTo，替换当前页面栈
        uni.redirectTo({
          url: `/pages/OrderDetailPage/OrderDetailPage?orderNo=${encodeURIComponent(this.orderData.orderNo)}`
        });
      } else {
        uni.showToast({ title: '无法跳转：缺少订单号', icon: 'none' });
      }
    }
  }
};
</script>

